export const questRouteData={"retrieved":"2026-11-22","routes":{"main":{"source":"https://oldschool.runescape.wiki/w/Optimal_quest_guide","revision":15411475,"steps":[{"id":"quest-learning-the-ropes","preparation":[],"notes":""},{"id":"quest-cooks-assistant","preparation":[],"notes":"Consider getting an extra pot of flour for Prince Ali Rescue . It is also recommended to start Rune Mysteries , The Restless Ghost and Prince Ali Rescue while in the area, to speed up completion of these quests later. For a more in-depth guide on which quests to combine to complete all Free-to-play quests as efficiently as possible, see the free-to-play version of this guide . From now on, this guide will not recommend multi-questing strategies."},{"id":"quest-sheep-shearer","preparation":[],"notes":"Consider getting an extra 3 balls of wool for the Prince Ali rescue quest."},{"id":"quest-misthalin-mystery","preparation":[],"notes":""},{"id":"quest-prince-ali-rescue","preparation":[],"notes":"Consider buying a sickle mould while in Al Kharid ."},{"id":"quest-the-restless-ghost","preparation":[],"notes":""},{"id":"quest-rune-mysteries","preparation":[],"notes":"Unlocks the ability to use lamps and books of knowledge on the Runecraft skill."},{"id":"quest-imp-catcher","preparation":["Unlock: Stronghold of Security · Requires RuneScape Authenticator to be set. Bring enough food and run through dangerous rooms as fast as possible, with auto-retaliate off. This rewards players with 10,000 from just the first three floors."],"notes":""},{"id":"quest-witchs-potion","preparation":[],"notes":""},{"id":"quest-gertrudes-cat","preparation":[],"notes":"Allows raising of cats . It is recommended to start raising a kitten to speed up Recipe for Disaster/Freeing Evil Dave and Ratcatchers ."},{"id":"quest-children-of-the-sun","preparation":[],"notes":"Allows access to Varlamore . Consider completing this quest whilst in Varrock Square during Gertrude's Cat to minimise time spent moving back and forth. Additionally, visit Varlamore once via Regulus Cento in order to unlock all other transportation methods to the region."},{"id":"quest-daddys-home","preparation":["Natural history quiz (miniquest)"],"notes":"Gives a player-owned house (POH) in Rimmington , as well as a valuable Marlo's crate ."},{"id":"quest-dwarf-cannon","preparation":[],"notes":"It is recommended to complete (or choose the option to skip) the Barbarian Assault tutorial, to unlock the minigame teleport . This makes it easier to reach the quest finish location more quickly. Or just use the teleport from a games necklace . Be sure to start the Alfred Grimhand's Barcrawl miniquest when you are there, and visit nearby bars while questing. Grants access to the dwarf multicannon and allows smithing of cannonballs . It may be advantageous to progress Doric's Quest and The Knight's Sword when visiting Nulodion near Falador for this quest."},{"id":"quest-mudfoots-big-adventure","preparation":[],"notes":"Use the Antique lamps on Prayer Prayer ."},{"id":"quest-ernest-the-chicken","preparation":[],"notes":"Use the Antique lamp on Agility Agility ."},{"id":"quest-waterfall-quest","preparation":[],"notes":"Speak to King Bolren part-way through the quest to start Tree Gnome Village and unlock Elkoy 's follow option."},{"id":"quest-tree-gnome-village","preparation":[],"notes":"Grants the ability to use spirit trees ."},{"id":"quest-dorics-quest","preparation":[],"notes":""},{"id":"quest-witchs-house","preparation":[],"notes":"Level 42 and 55 enemies can be safespotted ."},{"id":"quest-below-ice-mountain","preparation":[],"notes":""},{"id":"quest-the-birds-and-the-wasps","preparation":[],"notes":""},{"id":"quest-romeo-juliet","preparation":[],"notes":"Use the Antique lamp on Agility Agility ."},{"id":"quest-demon-slayer","preparation":[],"notes":"Use the Antique lamps on Prayer Prayer ."},{"id":"quest-black-knights-fortress","preparation":[],"notes":"Use both Antique lamps on Prayer Prayer ."},{"id":"quest-the-knights-sword","preparation":[],"notes":""},{"id":"quest-the-tourist-trap","preparation":[],"notes":"Choose Agility Agility for both experience rewards. This quest is done as soon as possible in order to improve run energy restoration and the speed of getting around. While the combat experience from Waterfall Quest and Tree Gnome Village may be helpful in completing it, this and the previous two quests could be done sooner if safespotting the Mercenary Captain ."},{"id":"quest-druidic-ritual","preparation":[],"notes":"Grants access to the Herblore skill. Players can start (but unadvised to attempt to finish) Dragon Slayer I after this quest to be allowed to equip the anti-dragon shield to make some quests easier. However this will enable dragon tasks for Slayer Slayer which give low experience per hour."},{"id":"quest-recruitment-drive","preparation":[],"notes":""},{"id":"quest-goblin-diplomacy","preparation":[],"notes":"While not yet necessary, it is easy to complete this quest while in Falador."},{"id":"quest-sleeping-giants","preparation":[],"notes":"Gives access to Giants' Foundry minigame. If you complete nine iron/steel sword commissions now, it will take care of Smithing training you will need later."},{"id":"quest-fight-arena","preparation":[],"notes":""},{"id":"quest-plague-city","preparation":[],"notes":"Grants the use of Ardougne teleport and Ardougne teleport (tablet) ."},{"id":"quest-monks-friend","preparation":[],"notes":""},{"id":"quest-hazeel-cult","preparation":[],"notes":"Useful for its 2,000 reward."},{"id":"quest-sheep-herder","preparation":[],"notes":"Useful for its 3,100 reward."},{"id":"quest-biohazard","preparation":[],"notes":""},{"id":"quest-tower-of-life","preparation":[],"notes":"Gives access to Creature Creation minigame."},{"id":"quest-tribal-totem","preparation":[],"notes":""},{"id":"quest-death-plateau","preparation":[],"notes":""},{"id":"quest-merlins-crystal","preparation":[],"notes":"Do not talk to Historian Minas after this quest. Instead, save up the lamp obtainable from him for later, when more skills are above level 20. This guide will indicate when to claim it later."},{"id":"quest-holy-grail","preparation":[],"notes":""},{"id":"quest-murder-mystery","preparation":[],"notes":""},{"id":"quest-the-writings-on-the-wall","preparation":[],"notes":""},{"id":"quest-the-grand-tree","preparation":[],"notes":"Allows use of gnome glider transportation system. Along with the earlier completion of Fight Arena , Holy Grail , Tree Gnome Village , and Witch's House , this unlocks the Nightmare Zone minigame teleport due to having five quest bosses unlocked."},{"id":"quest-a-ruff-situation","preparation":["Easy Ardougne Diary · Use the antique lamp on Agility Agility . This unlocks an infinite teleport to the Ardougne Monastery ."],"notes":"Unlocks dog pets , which can be traded in for blood runes at Ver Sinhaza ."},{"id":"quest-rag-and-bone-man-i","preparation":[],"notes":"It is recommended to start Rag and Bone Man II right after completing this quest, in order to obtain bones randomly throughout the world without actively hunting them. The skill requirements are not needed to start this sequel quest."},{"id":"quest-priest-in-peril","preparation":[],"notes":"Allows access to Morytania . Consider gathering all resources for both this quest and Nature Spirit to reduce travel back and forth."},{"id":"quest-nature-spirit","preparation":[],"notes":"It is recommended to pray at the Altar of Nature right after completing this quest, in order to complete an easy task in the Morytania Diary ."},{"id":"quest-pirates-treasure","preparation":[],"notes":"Optionally start out this quest, and only finish it when in Varrock for other quests. This may save a significant amount of time."},{"id":"quest-ghosts-ahoy","preparation":[],"notes":"The quest unlocks Ectophial and gives free access to Port Phasmatys ."},{"id":"quest-making-history","preparation":[],"notes":"Like before, do not claim the lamp from Historian Minas just yet."},{"id":"quest-the-ides-of-milk","preparation":[],"notes":"Use the magic lamp on Prayer ."},{"id":"quest-the-corsair-curse","preparation":[],"notes":"Unlocks access to the Feldip Hills via boat."},{"id":"quest-clock-tower","preparation":[],"notes":""},{"id":"quest-sea-slug","preparation":[],"notes":""},{"id":"quest-the-lost-tribe","preparation":[],"notes":"Allows access to Nardok's Bone Weapons where players can purchase the Dorgeshuun crossbow and bone bolts for early Ranged training."},{"id":"quest-death-to-the-dorgeshuun","preparation":[],"notes":""},{"id":"quest-elemental-workshop-i","preparation":[],"notes":""},{"id":"quest-icthlarins-little-helper","preparation":[],"notes":"The in-game quest guide lists a level 40 Agility recommendation, but this is not a hard requirement."},{"id":"quest-the-golem","preparation":[],"notes":""},{"id":"quest-the-ribbiting-tale-of-a-lily-pad-labour-dispute","preparation":[],"notes":"After finishing Children of the Sun , travelling to Varlamore may be done by talking to Regulus Cento , located just outside the eastern gate of Varrock ."},{"id":"quest-lost-city","preparation":[],"notes":"Grants the ability to make cosmic runes and to use the dragon dagger and the dragon longsword . It is recommended to cut and save two dramen branches for use in later quests."},{"id":"quest-fairytale-i-growing-pains","preparation":[],"notes":"Immediately start Fairytale II - Cure a Queen and progress until you unlock the fairy ring network (see that quest's guide), and leave the rest of the quest for later. Unlocking this greatly improves mobility around the world, and gives access to several Achievement Diary tasks."},{"id":"quest-recipe-for-disaster-another-cooks-quest","preparation":[],"notes":""},{"id":"quest-recipe-for-disaster-freeing-the-goblin-generals","preparation":[],"notes":""},{"id":"quest-pandemonium","preparation":[],"notes":""},{"id":"quest-prying-times","preparation":[],"notes":""},{"id":"quest-current-affairs","preparation":[],"notes":""},{"id":"quest-fishing-contest","preparation":[],"notes":""},{"id":"quest-recipe-for-disaster-freeing-the-mountain-dwarf","preparation":[],"notes":""},{"id":"quest-mountain-daughter","preparation":[],"notes":"Start The Giant Dwarf while in the area, for Ratcatchers ."},{"id":"quest-ratcatchers","preparation":[],"notes":"Requires starting The Giant Dwarf to access Keldagrim , but completion is not required. Unlocks lazy and wily cats , useful for catching hell-rats later on. To save time, one can easily grab Rat poison and complete Clock Tower when in Ardougne for Jimmy Dazzler . Additionally, complete The Feud while in Pollnivneach for the snake charmer ."},{"id":"quest-the-feud","preparation":[],"notes":"Complete the quest while in Pollnivneach for Ratcatchers ."},{"id":"quest-death-on-the-isle","preparation":[],"notes":""},{"id":"quest-alfred-grimhands-barcrawl","preparation":[],"notes":""},{"id":"quest-scorpion-catcher","preparation":[],"notes":"An Anti-dragon shield is highly recommended but not required."},{"id":"quest-the-dig-site","preparation":[],"notes":"Search the bookcase while in the exam centre to start Elemental Workshop II ."},{"id":"quest-elemental-workshop-ii","preparation":[],"notes":"Use a wizard's mind bomb to boost to level 20 Magic , if necessary."},{"id":"quest-a-souls-bane","preparation":[],"notes":""},{"id":"quest-enter-the-abyss","preparation":[],"notes":""},{"id":"quest-temple-of-the-eye","preparation":[],"notes":"Unlocks the Guardians of the Rift minigame."},{"id":"quest-x-marks-the-spot","preparation":[],"notes":"Use the antique lamp on Slayer Slayer ."},{"id":"quest-client-of-kourend","preparation":[],"notes":"Use both antique lamp rewards on Slayer Slayer ."},{"id":"quest-the-queen-of-thieves","preparation":[],"notes":""},{"id":"quest-the-depths-of-despair","preparation":[],"notes":""},{"id":"quest-a-porcine-of-interest","preparation":[],"notes":""},{"id":"quest-wanted","preparation":[],"notes":""},{"id":"quest-shield-of-arrav","preparation":[],"notes":"Use the Antique lamp on Slayer Slayer . You need a partner for this quest. This quest also gives access to another lamp when talking to Historian Minas ."},{"id":"quest-bone-voyage","preparation":["Unlock: Varrock Museum Kudos · Talk to Historian Minas just up the stairs and tell him the information about the displays to get the kudos and three antique lamps from the quests you've done. Use them on Slayer Slayer . Complete the cleaning finds part of Varrock Museum, to earn another 50 kudos . Combining these 50 kudos, the 28 kudos from the Natural History Quiz , and the 35 kudos from Historian Minas, this should put you on 113 kudos in total. Finally, talk to the information clerk to claim Mining 3,500 Mining and Crafting 2,500 Crafting experience."],"notes":"Unlocks Fossil Island , which gives access to ammonite crabs for combat training and possible fossil drops, and bird house trapping for fast Hunter Hunter experience. It is recommended to train Hunter on bird houses from now on."},{"id":"quest-watchtower","preparation":[],"notes":"Boost Mining with a dwarven stout ."},{"id":"quest-the-giant-dwarf","preparation":[],"notes":""},{"id":"quest-forgettable-tale","preparation":[],"notes":""},{"id":"quest-another-slice-of-h-a-m","preparation":[],"notes":"Unlocks the Dorgesh-Kaan–Keldagrim train system ."},{"id":"quest-vampyre-slayer","preparation":[],"notes":""},{"id":"quest-shadow-of-the-storm","preparation":[],"notes":"Use the experience reward on Ranged Ranged ."},{"id":"quest-horror-from-the-deep","preparation":[],"notes":""},{"id":"quest-animal-magnetism","preparation":[],"notes":"Unlocks access to Ava's devices ."},{"id":"quest-creature-of-fenkenstrain","preparation":[],"notes":""},{"id":"quest-big-chompy-bird-hunting","preparation":[],"notes":"Requires boosting Cooking Cooking by 3 levels by drinking a mature chef's delight , purchasable from the Grand Exchange for 33,913 . Alternatively, consider training Cooking Cooking to level 30."},{"id":"quest-jungle-potion","preparation":[],"notes":""},{"id":"quest-shilo-village","preparation":[],"notes":""},{"id":"quest-zogre-flesh-eaters","preparation":["Easy Karamja Diary · Use the antique lamp on Slayer Slayer ."],"notes":""},{"id":"quest-observatory-quest","preparation":[],"notes":"This quest has 12 variations of random rewards, which may include 875 experience in either Attack Attack , Strength Strength , Defence Defence , or Hitpoints Hitpoints ."},{"id":"quest-spirits-of-the-elid","preparation":[],"notes":""},{"id":"quest-garden-of-tranquillity","preparation":[],"notes":"After completion of the quest, consider waiting at the white tree to pick a fruit once it grows on it and complete a medium Varrock achievement diary task."},{"id":"quest-enlightened-journey","preparation":[],"notes":"Unlocks access to the balloon transport system ."},{"id":"quest-tears-of-guthix","preparation":["Unlock: Balloon transport system to Crafting Guild","Unlock: Balloon transport system to Varrock"],"notes":"Gives access to the Tears of Guthix minigame, which provides experience in your lowest skill."},{"id":"quest-in-search-of-the-myreque","preparation":[],"notes":""},{"id":"quest-shades-of-mortton","preparation":[],"notes":"Bank the diary of Herbi Flax and proceed to the next quest. You will claim its experience reward later. Buy 2 extra Swamp paste from Razmire Builders Merchants. For the next quest in the guide ( In Aid of the Myreque ) - You can also buy it from different places, but this way it's easy for convenience if you don't have it from before."},{"id":"quest-in-aid-of-the-myreque","preparation":[],"notes":""},{"id":"quest-skippy-and-the-mogres","preparation":[],"notes":"Required for killing mogres in Rag and Bone Man II"},{"id":"quest-troll-stronghold","preparation":[],"notes":"Grants the ability to make law runes ."},{"id":"quest-troll-romance","preparation":[],"notes":""},{"id":"quest-darkness-of-hallowvale","preparation":[],"notes":"Use all experience rewards on Slayer Slayer ."},{"id":"quest-a-shell-of-a-friend","preparation":[],"notes":""},{"id":"quest-underground-pass","preparation":[],"notes":"Training even higher Agility before doing this quest is recommended."},{"id":"quest-regicide","preparation":[],"notes":""},{"id":"quest-dragon-slayer-i","preparation":[],"notes":"Starting this quest unlocks dragons Slayer tasks, and access to anti-dragon shields and antifire potions . These tasks give low experience per hour, so it can be beneficial not to start this quest any earlier."},{"id":"quest-the-fremennik-trials","preparation":[],"notes":"The Crafting/Woodcutting/Fletching requirements listed in the in-game interface can be bypassed by killing Lanzig , Borrokar , Lensa , or Freidir for the lyre instead of needing to make it yourself."},{"id":"quest-the-fremennik-isles","preparation":[],"notes":"Choose Defence Defence for both experience rewards."},{"id":"quest-recipe-for-disaster-freeing-evil-dave","preparation":[],"notes":"Gives access to spicy stews , which can be useful for boosting stats."},{"id":"quest-recipe-for-disaster-freeing-pirate-pete","preparation":[],"notes":""},{"id":"quest-tai-bwo-wannai-trio","preparation":[],"notes":"Return to the brothers after completing the quest to claim all experience rewards."},{"id":"quest-contact","preparation":["Easy Kandarin Diary · Use antique lamp on Smithing Smithing . Keep Kandarin Headgear in inventory for the next quest, Contact!"],"notes":"Safespot the Giant Scarab with Magic and Protect from Missiles active. Use the combat lamp on Magic Magic twice."},{"id":"quest-temple-of-ikov","preparation":[],"notes":""},{"id":"quest-the-eyes-of-glouphrie","preparation":[],"notes":"Unlocks access to the crystal saw , which gives an invisible +3 boost to Construction ."},{"id":"quest-one-small-favour","preparation":[],"notes":"Use the antique lamps on Slayer Slayer ."},{"id":"quest-the-ascent-of-arceuus","preparation":[],"notes":""},{"id":"quest-tale-of-the-righteous","preparation":[],"notes":""},{"id":"quest-the-forsaken-tower","preparation":[],"notes":""},{"id":"quest-between-a-rock","preparation":["Easy Desert Diary · Use all antique lamps on Smithing Smithing .","Easy Fremennik Diary","Easy Falador Diary","Easy Kourend & Kebos Diary","Easy Lumbridge & Draynor Diary","Easy Morytania Diary","Easy Varrock Diary","Easy Western Provinces Diary","Easy Wilderness Diary"],"notes":""},{"id":"quest-the-slug-menace","preparation":[],"notes":""},{"id":"quest-getting-ahead","preparation":[],"notes":""},{"id":"quest-cold-war","preparation":["Unlock: Museum Camp · View the bulletin board and complete every camp improvement then claim your reward from Peter . Clean the fossils and add them to the paleontology floor (in the basement) of the Varrock Museum . Click a small display to add them to it. Use the antique lamp on Herblore Herblore ."],"notes":"Use the workshop and crafting table 3 you built previously in your POH to save time for this quest."},{"id":"quest-the-hand-in-the-sand","preparation":[],"notes":""},{"id":"quest-enakhras-lament","preparation":[],"notes":""},{"id":"quest-eadgars-ruse","preparation":[],"notes":"Boost to Herblore 31 Herblore using a botanical pie , or train up to level 31 herblore before starting the quest. Collect and keep two extra goutweed herbs from the storage for use in later quests."},{"id":"quest-my-arms-big-adventure","preparation":[],"notes":"Requires 60% Tai Bwo favour to start. It is recommended to get 100% for the medium Karamja Diary task before losing 60% favour during this quest."},{"id":"quest-the-garden-of-death","preparation":[],"notes":""},{"id":"quest-rag-and-bone-man-ii","preparation":[],"notes":""},{"id":"quest-crab-quest","preparation":[],"notes":""},{"id":"quest-rum-deal","preparation":[],"notes":"Before the quest, pray at the Edgeville Monastery to have 47 Prayer points needed for this quest."},{"id":"quest-cabin-fever","preparation":[],"notes":""},{"id":"quest-meat-and-greet","preparation":[],"notes":""},{"id":"quest-recipe-for-disaster-freeing-the-lumbridge-guide","preparation":[],"notes":""},{"id":"quest-recipe-for-disaster-freeing-skrach-uglogwee","preparation":[],"notes":""},{"id":"quest-heroes-quest","preparation":[],"notes":"Use an Admiral pie to boost to 53 Fishing , and a Chef's delight to boost 53 Cooking ."},{"id":"quest-throne-of-miscellania","preparation":[],"notes":"Gives access to Managing Miscellania ."},{"id":"quest-royal-trouble","preparation":[],"notes":""},{"id":"quest-haunted-mine","preparation":[],"notes":""},{"id":"quest-lair-of-tarn-razorlor","preparation":[],"notes":"If you have a Slayer ring you can teleport directly to the boss. If you don't have one you'll need to traverse a maze while constantly being attacked, it's advised to bring a lot of food, at least 1 stamina potion and 2 prayer potions , making sure to keep at least 1 for the final boss fight. After killing the boss also kill one of the two terror dogs to fulfil a medium Morytania Diary task."},{"id":"quest-monkey-madness-i","preparation":[],"notes":"Talk to Daero for 35,000 experience in Attack Attack and Defence Defence and 20,000 experience in Strength Strength and Hitpoints Hitpoints ."},{"id":"quest-ethically-acquired-antiquities","preparation":[],"notes":""},{"id":"quest-twilights-promise","preparation":[],"notes":"Ability to use the Civitas illa Fortis Teleport spell and the Quetzal Transport System in Varlamore"},{"id":"quest-roving-elves","preparation":[],"notes":""},{"id":"quest-mournings-end-part-i","preparation":[],"notes":""},{"id":"quest-mournings-end-part-ii","preparation":[],"notes":"Consider training Agility to ~65 and/or bringing summer pies before doing this quest to improve success rates at passing the Agility obstacle in the puzzle."},{"id":"quest-desert-treasure-i","preparation":[],"notes":"Unlocks the ability to use Ancient Magicks ."},{"id":"quest-family-crest","preparation":[],"notes":"Boost magic using a magic potion , or alternatively train 2 more levels and boost using a wizard's mind bomb . Unlocks steel gauntlets which can be useful when training Smithing , Cooking or Magic ."},{"id":"quest-what-lies-below","preparation":[],"notes":"Unlocks access to battlestaves in Zaff's Superior Staffs!"},{"id":"quest-eagles-peak","preparation":[],"notes":"Unlocks box trap hunting."},{"id":"quest-a-tail-of-two-cats","preparation":[],"notes":"Use both Antique lamps on Herblore Herblore ."},{"id":"quest-legends-quest","preparation":[],"notes":"Use a botanical pie to boost to level 45 Herblore . Use all the experience rewards on Herblore Herblore ."},{"id":"quest-land-of-the-goblins","preparation":[],"notes":"You may bank between the fights if you have to, but you'll need to make an extra goblin potion if you want to do that."},{"id":"quest-recipe-for-disaster-freeing-sir-amik-varze","preparation":[],"notes":""},{"id":"quest-olafs-quest","preparation":[],"notes":""},{"id":"quest-a-kingdom-divided","preparation":[],"notes":"Unlocks more spells in the Arceuus spellbook . Use both antique lamps on Slayer Slayer ."},{"id":"quest-a-taste-of-hope","preparation":[],"notes":"To start the quest you can use Ectophial to teleport you near Andras who will take you north of the starting location for 10,000gp. Use tome of experience on Slayer Slayer ."},{"id":"quest-at-first-light","preparation":[],"notes":"Access to Master Tier Hunters' Rumours. This shouldn't require much training if birdhouses were done during prior quests."},{"id":"quest-a-new-leaf","preparation":[],"notes":"Protects allotment guild patches in the Farming Guild from disease."},{"id":"quest-curse-of-the-empty-lord","preparation":["Unlock: Balloon transport system to Castle Wars","Medium Ardougne Diary · Note that killing the necessary 125 Chompy birds rewards Hunter experience and may be done as part of the above hunter training. Use a crystal saw , hunter potion , botanical pie for necessary boosts. Use all antique lamps on Slayer Slayer . 70 Combat Level is required for the Lumbridge Diary.","Medium Desert Diary","Medium Falador Diary","Medium Fremennik Diary","Medium Kandarin Diary","Medium Kourend & Kebos Diary","Medium Lumbridge & Draynor Diary","Medium Morytania Diary","Medium Varrock Diary","Medium Western Provinces Diary"],"notes":"Requires starting Desert Treasure I and obtaining the ring of visibility ."},{"id":"quest-the-generals-shadow","preparation":[],"notes":"Requires the ring of visibility ."},{"id":"quest-his-faithful-servants","preparation":["Unlock: More Varrock Museum Kudos · Talk to Historian Minas to claim a 10,000 experience antique lamp to use on Slayer Slayer . Note that in order to receive kudos for What Lies Below , you will need to bring Dagon'hai history with you. You now have 151 kudos. Talk to the information clerk to be awarded 4,000 experience in Crafting Crafting , Hunter Hunter , Prayer Prayer , Slayer Slayer and Smithing Smithing ."],"notes":"Provides a large amount of Prayer experience. The melee Barrows brothers can be kited in their sarcophagus room."},{"id":"quest-the-great-brain-robbery","preparation":[],"notes":"Use the blessed lamp on Slayer Slayer ."},{"id":"quest-scrambled","preparation":[],"notes":""},{"id":"quest-fairytale-ii-cure-a-queen","preparation":[],"notes":"Use a botanical pie and garden pie to boost Herblore and Farming . Use the antique lamp on Slayer Slayer ."},{"id":"quest-recipe-for-disaster-freeing-king-awowogei","preparation":[],"notes":"Use a chef's delight to boost Cooking to 70."},{"id":"quest-recipe-for-disaster-defeating-the-culinaromancer","preparation":[],"notes":"Use the antique lamp on Slayer Slayer ."},{"id":"quest-perilous-moons","preparation":[],"notes":"If you have focused on questing and not done much combat, these quest bosses will be significantly harder than anything faced before. Even at the recommended 75 combat level, players may struggle if their defence is lower than 60. Prioritise bringing defensive equipment."},{"id":"quest-the-path-of-glouphrie","preparation":[],"notes":""},{"id":"quest-the-heart-of-darkness","preparation":[],"notes":""},{"id":"quest-lunar-diplomacy","preparation":[],"notes":"Unlocks the Lunar spellbook 's core spells."},{"id":"quest-kings-ransom","preparation":[],"notes":"Use the antique lamp on Slayer Slayer ."},{"id":"quest-swan-song","preparation":["Knight Waves Training Grounds (miniquest)"],"notes":"Use an admiral pie to boost to 62 Fishing . Bring multiple in case you don't manage to catch enough fish in time the pie runs out."},{"id":"quest-defender-of-varrock","preparation":[],"notes":"After the quest, talk to Historian Minas for an antique lamp. Use the antique lamp on Slayer Slayer ."},{"id":"quest-rag-and-bone-man-iii","preparation":[],"notes":"Unlocks the ability to upgrade the bonesack into the heavy bonesack, which can hold 28 bones."},{"id":"quest-devious-minds","preparation":[],"notes":""},{"id":"quest-grim-tales","preparation":[],"notes":"Use a dragon axe special attack or stews to boost Woodcutting to 71."},{"id":"quest-dream-mentor","preparation":[],"notes":"Unlocks additional spells in the Lunar spellbook . Use the Dreamy lamp on Magic Magic ."},{"id":"quest-the-fremennik-exiles","preparation":["Medium Karamja Diary · Use an admiral pie to boost to 65. Use antique lamp on Slayer Slayer .","Medium Wilderness Diary · Use antique lamp on Slayer Slayer ."],"notes":""},{"id":"quest-sins-of-the-father","preparation":[],"notes":"Use the tome of experience on Slayer Slayer ."},{"id":"quest-in-search-of-knowledge","preparation":["Unlock: Balloon transport system to Grand Tree"],"notes":"Use the lamp of knowledge on Slayer Slayer . This miniquest will take a very long time to complete on its own. It is recommended to kill monsters in the Forthos Dungeon while on a spiders , zombies , or red dragons Slayer task, to passively obtain the required pages."},{"id":"quest-hopespears-will","preparation":[],"notes":"Provides a large amount of Prayer experience. Can be partially completed for part of the experience reward, in case some of the enemies are too difficult to defeat."},{"id":"quest-beneath-cursed-sands","preparation":[],"notes":""},{"id":"quest-shadows-of-custodia","preparation":[],"notes":""},{"id":"quest-troubled-tortugans","preparation":[],"notes":""},{"id":"quest-the-red-reef","preparation":[],"notes":""},{"id":"quest-fallen-from-grace","preparation":[],"notes":""},{"id":"quest-monkey-madness-ii","preparation":[],"notes":"Choose Magic Magic when asked during Duke 's training."},{"id":"quest-into-the-tombs","preparation":[],"notes":"Use the antique lamp on Magic Magic ."},{"id":"quest-a-night-at-the-theatre","preparation":[],"notes":"Use all four antique lamps on Magic Magic ."},{"id":"quest-dragon-slayer-ii","preparation":[],"notes":"An additional 4 batches of 25,000 experience in any combat skill except Prayer can be obtained from Ellen . Select either Attack or Strength ; Attack is chosen here for all 4 batches."},{"id":"quest-the-curse-of-arrav","preparation":[],"notes":""},{"id":"quest-making-friends-with-my-arm","preparation":[],"notes":"Use a dwarven stout or dragon pickaxe to boost Mining ."},{"id":"quest-secrets-of-the-north","preparation":[],"notes":""},{"id":"quest-the-final-dawn","preparation":[],"notes":"Although the antique lamp could be used on Attack Attack or Strength Strength to speed up quest progression, it is more sensible to use it on Prayer Prayer for purposes of account progression."},{"id":"quest-while-guthix-sleeps","preparation":[],"notes":""},{"id":"quest-desert-treasure-ii-the-fallen-empire","preparation":[],"notes":"Use the three ancient lamps on any combat skill of your choosing. Prayer is selected here."},{"id":"quest-song-of-the-elves","preparation":[],"notes":""},{"id":"quest-the-blood-moon-rises","preparation":[],"notes":"Use the six experience tomes on any skill/s of your choosing above level 70. Slayer is selected here."}]},"ironman":{"source":"https://oldschool.runescape.wiki/w/Optimal_quest_guide/Ironman","revision":15411925,"steps":[{"id":"quest-learning-the-ropes","preparation":[],"notes":"On first arrival in Lumbridge : Pickpocket a nearby man for an easy Lumbridge Diary task. Buy a spade from the Lumbridge General Store , using 3 coins from the coin pouch you just pickpocketed. Start X Marks the Spot by speaking to Veos in The Sheared Ram . Dig by Bob's Axe Shop for X Marks the Spot . Learn your age from Hans for an easy Lumbridge Diary task. He can be found patrolling around the outside of the castle. Dig behind Lumbridge Castle for X Marks the Spot . Kill a nearby giant rat and take the raw rat meat for Druidic Ritual . Pick up the bones for an easy Varrock Diary task. Bank your inventory on the 2 nd floor [ UK ] 3 rd floor [ US ] of Lumbridge Castle , keeping only the pot and bucket , in order to have enough inventory space for the following steps. Pick up nearby logs until you have at least 17 ( world hop to restock) and bank these for Daddy's Home , Tree Gnome Village and Monk's Friend . A total of 30 logs are required to complete all quests."},{"id":"quest-cooks-assistant","preparation":[],"notes":"Start the quest by talking to the Cook in the kitchen on the ground floor. Pick up an additional pot from the nearby table, and a bucket from the Lumbridge Castle cellar. Gather the egg, flour, and milk on the west side of the River Lum . Fill a second pot of flour at the windmill for an easy Lumbridge Diary task. Fill a second bucket of milk at the cow pen for Gertrude's Cat . Kill a chicken for feathers for Client of Kourend and raw chicken for Druidic Ritual while in the chicken pen to pick up the egg . Before returning to the Cook to complete the quest, start Sheep Shearer by talking to Fred the Farmer and gather 20 wool from the sheep in the nearby pen. After quest completion, pick up a bucket from the cellar and fill it at the sink . Use it on your pot of flour to create bread dough . Use the bread dough on the range for an easy Lumbridge Diary task."},{"id":"quest-sheep-shearer","preparation":[],"notes":"Spin the wool at the spinning wheel on the 1 st floor [ UK ] 2 nd floor [ US ] of the castle. Speak to Duke Horacio on the same floor to start Rune Mysteries . Return to Fred the Farmer to complete Sheep Shearer . After quest completion, pick an onion from the field behind Fred's house for Witch's Potion ."},{"id":"quest-the-restless-ghost","preparation":[],"notes":"Start the quest by talking to Father Aereck in the Lumbridge church . Ensure you have not banked your air talisman given to you by Duke Horacio. On the way to Father Urhney , stop by the south-eastern corner of Lumbridge Swamp near the fishing spots and speak to Abigale to start Misthalin Mystery . Complete it before continuing. After speaking to Father Urhney, pick up the leather gloves , as these are required for numerous quests. While at the Wizards' Tower , bring the air talisman to Archmage Sedridor in the basement for the second step of Rune Mysteries ."},{"id":"quest-misthalin-mystery","preparation":[],"notes":"Complete during The Restless Ghost."},{"id":"quest-x-marks-the-spot","preparation":[],"notes":"While in Draynor Village : Start Vampyre Slayer by talking to Morgan , taking garlic from the cupboard upstairs for the quest. Take three additional pieces for Fishing Contest , Desert Treasure I and While Guthix Sleeps . Do a lap of the Draynor Agility Course for an easy Lumbridge Diary task. Bank everything except your coins , onion , and feathers before completing the quest in Port Sarim . After completion of this quest use the 300 experience reward on Agility Agility ."},{"id":"quest-witchs-potion","preparation":[],"notes":"While in Port Sarim : From Betty's Magic Emporium buy two eye of newt , one for this quest and one for Another Cook's Quest . From Gerrant's Fishy Business , buy a raw sardine for Gertrude's Cat and a fishing bait for Recipe for Disaster/Freeing the Goblin generals . From Wydin 's Food Store buy 6 pieces of cheese for Witch's House , Ratcatchers and Mourning's End Part II 's item list . Buy two pieces of raw beef , one for this quest and one for Druidic Ritual (hop worlds to restock). Burn one raw beef at the range north of the food store for this quest (cook it twice)."},{"id":"quest-client-of-kourend","preparation":[],"notes":"Use the Minecart network to travel throughout the quest, which costs 20 per trip. While in Shayzien : Pick up the black wizard hat off the table in the clothing shop Shayzien Styles for Shadow of the Storm . Pick up 25 bones by the Shayzien West minecart for Demon Slayer - you can bank them at Shayzien to the east. When activating the mysterious orb near the Dark Altar , talk to Tyss to change your spellbook to Arceuus spellbook for a medium Kourend & Kebos Diary task. You may change it back after completing the task. Return to Port Sarim and talk to Redbeard Frank to start Pirate's Treasure . After completion of this quest use both 500 experience rewards on Agility Agility ."},{"id":"quest-pandemonium","preparation":[],"notes":"Keep the sawmill coupons from the quest reward for Daddy's Home and other quests requiring planks. After completing the quest: Head north-west to Pandemonium Cave and talk to Chartin' Charles McAtless to receive a spyglass for use in Sea charting . Use your spyglass to admire Chartin' Charles McAtless in the Pandemonium Cave . Use your spyglass to get a good view of the Pandemonium from the Pandemonium Cave entrance. Return to Port Sarim via charter ship."},{"id":"quest-children-of-the-sun","preparation":["Partially complete: Pirate's Treasure · Purchase a small fishing net at Gerrant's Fishy Business . Travel to Musa Point (Karamja) via charter ship for 30 . Complete all of the quest steps in Musa Point. Fish at the fishing spot to the north for an easy Karamja Diary task. Return to Port Sarim via the charter ship to complete another easy Karamja Diary task. Complete all of the quest steps in Port Sarim. Keep the White apron for Mourning's End Part II 's item list .","Unlock: Stronghold of Security · Requires RuneScape Authenticator to be set. On your way to the Barbarian Village , purchase an inventory of jugs of wine from Fortunato in Draynor Village for 1 coin each, a cheap source of food to help you pass the Stronghold. At Barbarian Village climb down the entrance in between the Coal and Tin rocks. Run through dangerous rooms as fast as possible, with auto-retaliate off. This rewards players with 10,000 from just the first three floors. Return to Draynor Village to use some of the coins to purchase the Chronicle , along with 10-15 teleport cards to charge it. This can be used to teleport to the Champions' Guild near Varrock for the following quests. While in Draynor Village, also purchase 2 ropes from Ned for Plague City and Waterfall Quest ."],"notes":"Allows access to Varlamore . While in the Varrock town square: Look for a nearby stray dog and use bones on it for an easy Varrock Diary task. Buy a newspaper from Benny in the town square for an easy Varrock Diary task. Purchase 3 silk from Thessalia's Fine Clothes for the easy Ardougne Diary (keep for future quests). Also buy a pink skirt for Prince Ali Rescue . Talk to Dr Harlow at the Blue Moon Inn south of the square for Vampyre Slayer . Continue Pirate's Treasure by using the chest key on the chest upstairs. You can now complete the quest the next time the guide takes you to Falador . Bring the research package to Aubury in the rune shop to the east of the inn for Rune Mysteries ."},{"id":"quest-gertrudes-cat","preparation":[],"notes":"Allows raising of cats . Raise a kitten to a cat to speed up Recipe for Disaster/Freeing Evil Dave and Ratcatchers . Note: Raw karambwanji is a stackable fish that can be fed to cats. Consider catching some on the next trip to Karamja. On your way past the museum complete the Natural history quiz in the Varrock Museum basement. Before the Lumber yard step: Start Daddy's Home by talking to Marlo in the house of the Varrock Estate Agent in north-east Varrock. Go to Old Man Yarlo 's house south-west of Aubury's Rune Shop , talk to him and complete his tasks. Talk to him again and watch the cutscene. Now search the crates in the kitchen for three waxwood logs . Bring the following for the Lumber Yard step: An Axe Bucket of milk Seasoned sardine , or create them from: Raw sardine , bought from the fishing shop at Port Sarim Doogle leaves , found behind Gertrude 's house. 3 waxwood logs 10 logs and 10 sawmill coupons (wood plank) received from the Pandemonium quest 3,600 - 4,000 (+1000 extra if not bringing coupons for the planks) On the way to the Lumber Yard: Talk to Regulus Cento to travel to Civitas illa Fortis and back - this will unlock other transportation methods to Varlamore . Before returning, you may also consider picking up the Black wizard robe from the 2 nd floor [ UK ] 3 rd floor [ US ] of the pub just south of the Quetzal for an early Magic bonus. Get waxwood planks , 10 regular planks , 5 bolts of cloth and around 100 bronze nails from the sawmill operator for the final step of Daddy's Home . Also buy 150 steel nails for Dragon Slayer I and Horror from the Deep . Cut down a dying tree for an easy Varrock Diary task. On your way back to Gertrude to finish the quest, return to Old Man Yarlo to finish Daddy's Home . Bank the steel nails beforehand, or they will be used instead of the bronze nails when constructing the furniture. Save the stew reward for The Queen of Thieves , and the chocolate cake for A Tail of Two Cats ."},{"id":"quest-demon-slayer","preparation":["Daddy's Home · Complete during Gertrude's Cat . This quest rewards you with: 25 Planks (Keep all of them for future quests; you will need at least 35 planks to complete all quests) 50 Mithril nails (Use whenever quests require nails) 5 Steel bars (You will need 1 for Prying Times , 2 for In Aid of the Myreque , 4 for One Small Favour , and 6 for Desert Treasure I ) 10 Oak planks (Keep for Cold War ) 8 bolts of cloth (Keep 1 for Making Friends with My Arm )","Natural history quiz (miniquest) · Complete during Gertrude's Cat ."],"notes":"Start the quest in the Varrock town square, and write down the incantation from the cutscene (differs per player). Complete the quest steps in the Varrock Palace to retrieve two of the three keys. Travel to Draynor Village . If you don't already have 25 bones , kill goblins by the jail east of the village. Take the bones and research notes from Rune Mysteries and head to the Wizards' Tower . Complete Rune Mysteries by talking to Archmage Sedridor in the basement. Teleport from Archmage Sedridor to the Rune Essence Mine for an easy Lumbridge Diary task. Retrieve the final key for this quest by giving the bones to Wizard Traiborn on the 1 st floor [ UK ] 2 nd floor [ US ] . Return to Varrock , taking the three silverlight keys you gathered for Demon Slayer to Sir Prysin to retrieve Silverlight . Take food and silverlight to the stone circle by the southern entrance to Varrock and defeat Delrith with the incantation to complete Demon Slayer . Use both lamps on Prayer Prayer ."},{"id":"quest-rune-mysteries","preparation":[],"notes":"Unlocks the ability to use lamps and books of knowledge on the Runecraft skill. Complete during Demon Slayer ."},{"id":"quest-tree-gnome-village","preparation":["Partially complete: Enter the Abyss · Start the quest by talking to the Mage of Zamorak in the Wilderness to the north of the Edgeville slayer master. Talk to him again in south-eastern Varrock at the Varrock chaos temple until he gives you a scrying orb . With the scrying orb , visit the rune essence mine via Aubury at Aubury's Rune Shop in Varrock to complete the first task. Take a pickaxe and collect 71 rune essence (50 for Priest in Peril , and an additional 21 for Wanted! , The Slug Menace and Garden of Tranquillity ). Purchase roughly 300+ mind runes from Aubury , as well as 6 air runes , 6 water runes and 6 earth runes for Waterfall Quest . Also purchase an air staff from Zaff . Using wind strike will allow you to safespot for some early game quests like Tree Gnome Village and Fight Arena ."],"notes":"Allows the use of spirit trees . Optional : Hardcore ironmen may consider completing Witch's House first for the safety of the additional hitpoints. Bring your coins and 7 logs with you, and travel to Rimmington (you can use the teleport to house tablet you got from Marlo's Crate ). Collect three pieces of snape grass at the Hobgoblin Peninsula to the north for Plague City , Skippy and the Mogres and Fairytale I - Growing Pains . Use the ship west of Rimmington to travel to Ardougne for 30 . Walk south-west from Ardougne and enter the Gnome maze to start the quest. Purchase a jug to fill with water for Monk's Friend , from Bolkoy's Village Shop upstairs in the centre of the maze. After completing this quest, use the spirit tree to teleport to the Battlefield of Khazard and enter the house to the north to start Hazeel Cult ."},{"id":"quest-hazeel-cult","preparation":[],"notes":"If siding with Ceril , the quest will be faster but you will need to defeat a level 13 Hazeel Cultist . There will also be two \"rewards\". The first is 5 coins. Find the poison in the cupboard upstairs on the 1 st floor [ UK ] 2 nd floor [ US ] for the second reward: 2,000 coins and 1,500 experience in Thieving Thieving . Siding with Hazeel gives you the full reward at once. After completion of this quest: Steal from the bakery stall in the Ardougne Market until you have one cake for an easy Ardougne Diary task and two breads for Merlin's Crystal and Below Ice Mountain . Optional : The bakery stall will be a great source of early food, as cake heals for a total of 12 hitpoints. Consider stocking up on some now before Fight Arena and Waterfall Quest . Buy 4 silver bars from the Ardougne Silver Stall (hop worlds to restock) for Nature Spirit , Shadow of the Storm , Creature of Fenkenstrain , and to craft a mind tiara later for an easy Falador Diary task."},{"id":"quest-clock-tower","preparation":[],"notes":"Pick up an extra bottle of rat poison for Ratcatchers ."},{"id":"quest-monks-friend","preparation":[],"notes":"Get the bucket near Brother Cedric and fill it with water at the well. Use the bucket of water on the empty jug to get a jug of water for this quest. After completion of this quest: Take the lit candle from the Ardougne Monastery for retrieving boots of lightness later. Take the Battlefield spirit tree to the Tree Gnome Stronghold . Pick some nearby flax for Mourning's End Part II 's item list , then retrieve your scrying orb and coins from the nearby bank. At Brimstail's cave in the south-western section of the stronghold, have Brimstail teleport you to the rune essence mine with the scrying orb in your inventory for the second Enter the Abyss task. Head to the north-western corner of the 1 st floor [ UK ] 2 nd floor [ US ] of the Grand Tree and purchase two buckets of milk , two chocolate dust and four dwellberries from Grand Tree Groceries . Use the chocolate dust on the bucket of milk to create two lots of chocolatey milk . Use snape grass on each to create two hangover cures for Plague City and Skippy and the Mogres . Keep the dwellberries for Plague City and The Curse of Arrav . Note that you won't be able to return to the Battlefield via the spirit tree. Walk south-east from the stronghold into northern East Ardougne to start Plague City instead."},{"id":"quest-plague-city","preparation":[],"notes":"Allows use of the Ardougne teleport spell."},{"id":"quest-biohazard","preparation":[],"notes":"After beginning the quest and when you are sent near the West Ardougne gate, enter the house to the north and pull the Wilderness lever to complete an easy Ardougne Diary task (pull it again to return). Before leaving Ardougne for Rimmington, take your scrying orb and teleport via Wizard Cromperty to the rune essence mine to complete an easy Ardougne Diary task, as well as the third location for Enter the Abyss . Take the orb along for the rest of the quest to complete Enter the Abyss during it. When in Rimmington , buy a sickle mould at Rommik's Crafty Supplies for Nature Spirit (it's useful to buy all available moulds here, like the holy mould ). When visiting the Dancing Donkey Inn in Varrock , steal from the tea seller to the north for an easy Varrock Diary task. Keep the cup of tea for The Dig Site . During the Dancing Donkey Inn section, hand in your scrying orb to the Mage of Zamorak to complete Enter the Abyss . Keep both priest gown items for use in Shadow of the Storm ."},{"id":"quest-enter-the-abyss","preparation":[],"notes":"Complete during Biohazard ."},{"id":"quest-temple-of-the-eye","preparation":["Easy Ardougne Diary · Complete the remaining diary tasks in the following order: Enter the Combat Training Camp north of West Ardougne . Use the altar in the East Ardougne church . Check what pets you have insured with Probita . Sell silk to the silk trader in the Ardougne Market by offering to sell for 120 coins, then counter his bid with 60 coins. Obtain a rusty sword by entering the H.A.M. Hideout north-west of Lumbridge and pickpocketing H.A.M. members . Note: There is a 1/100 chance you will require an additional sword. If you receive buttons , uncut opal , uncut jade , cowhide , or any herbs, keep them for future quests. Use the Castle Wars Minigame Teleport and head to Yanille . Visit Aleck's Hunter Emporium for the task, and purchase a bird snare to be used later for an easy Desert Diary task. Head to Port Khazard and give your rusty sword and 100 coins to Tindel Marchant . Purchase swamp paste at the Khazard General Store for Sea Slug . At the mine to the south-west collect 18 copper ore , 14 tin ore and 2 iron ore . After mining the ore, board the Fishing Trawler . Once the trawler is out at sea, talk to Murphy to attempt to return to land. After capsizing, climb onto the nearby barrel to return to the mainland. Complete the diary by talking to Two-pints at the Flying Horse Inn . After completion, smelt 14 copper and 14 tin ore into bronze bars for Observatory Quest , Prince Ali Rescue , One Small Favour , The Tourist Trap , Creature of Fenkenstrain , Recipe for Disaster/Freeing Pirate Pete , Shilo Village , and Mourning's End Part II 's item list . The rest of the ores are for Doric's Quest . Obtaining the Ardougne cloak 1 gives you the following main benefits: An infinite teleport to the Ardougne Monastery with close proximity to an altar , spirit tree and fairy ring . Double death runes (200) for trading in cats to civilians in West Ardougne . Best early obtainable combat stats in the cape slot . The antique lamp can only be used in a skill over 30 and cannot be banked. If following the guide exactly, it is recommended to put it on Prayer - you should hit level 30 at Holy Grail ."],"notes":"Unlocks Guardians of the Rift ."},{"id":"quest-fight-arena","preparation":[],"notes":""},{"id":"quest-tribal-totem","preparation":[],"notes":"While in The Shrimp and Parrot to start the quest, purchase a tuna for Family Crest . Travel to Ardougne via Captain Barnaby with 30 coins after starting the quest to complete an easy Karamja Diary task. Keep one swordfish from the quest reward for Family Crest ."},{"id":"quest-sheep-herder","preparation":[],"notes":"Good luck and do not lose your sanity! This is a good time to collect your boots of lightness : Take the lit candle from the Ardougne Monastery or your bank. Purchase the following from Aemad's Adventuring Supplies : Knife to collect the boots of lightness 12 balls of wool for Enlightened Journey , Recipe for Disaster/Freeing Skrach Uglogwee , Prince Ali Rescue , Monkey Madness I , Regicide , Making History , and Mourning's End Part II 's item list . 12 papyrus for The Golem , Enlightened Journey , Legends' Quest , and While Guthix Sleeps . A water-filled vial pack . Vials of water are required for numerous quests, and can also be used to turn clay into soft clay . It will also be required to create a number of potions for future quests. An iron axe for Mourning's End Part II 's item list . While near the sheep, take the knife and lit candle and head to the Temple of Ikov and enter it. Head directly west and descend the stairs. Slash the web at the other end of the room and pick up the boots."},{"id":"quest-waterfall-quest","preparation":["Partially complete: Dwarf Cannon · Complete up until Captain Lawgof asks you to visit Nulodion at the dwarven base; the quest will be completed next time the guide takes you near the Dwarven Mine.","Unlock: Barbarian Assault teleport Partially complete: Alfred Grimhand's Barcrawl · Visit the Barbarian Outpost to complete the Barbarian Assault tutorial for the minigame teleport. Start Alfred Grimhand's Barcrawl by talking to the Barbarian guard by the gate to the east of the Barbarian Assault building. This miniquest involves visiting bars with the barcrawl card and buying alcohol from the bartender, and can be passively completed while doing other quests. Visit The Flying Horse Inn in Ardougne and drink a Heart Stopper for Alfred Grimhand's Barcrawl ."],"notes":"After talking to Golrie near the Tree Gnome Village , use the spirit tree to visit the Blurberry Bar at the Grand Tree (also buy a Premade blurb' sp . for Death Plateau ) Hardcore ironmen may choose to complete Witch's House first for the additional Hitpoints levels to make this quest safer. Keep the mithril seeds for Song of the Elves ."},{"id":"quest-murder-mystery","preparation":[],"notes":"While at the Poison Salesman step in the Forester's Arms , complete the Alfred Grimhand's Barcrawl step."},{"id":"quest-dorics-quest","preparation":["Partially complete: Merlin's Crystal · While in Catherby , grab an extra bucket of wax for Troll Romance . Complete the quest up until you need to visit the Lady of the Lake in Taverley . Complete this step while completing the following three quests."],"notes":"Before starting this quest, mine 16 clay from the mine by the Champions' Guild . 6 are required for this quest, and the rest can be turned into soft clay using vials of water when required for future quests. The Falador teleport tablet received from Daddy's Home may be used to get to the quest area. Bring the required items for this quest, Druidic Ritual and Witch's House (including combat gear) to quickly complete these three quests together. You can kill a black bear to the east of Doric on the hill for raw bear meat for Druidic Ritual . Visit the Dwarven Mine to the east of Taverley to receive the ammo mould and Nulodion's notes from Nulodion for the Dwarf Cannon step. Talk to the Lady of the Lake for the Merlin's Crystal step."},{"id":"quest-druidic-ritual","preparation":[],"notes":"Grants access to the Herblore skill."},{"id":"quest-witchs-house","preparation":[],"notes":"Forms 3 and 4 of Witch's experiment are easily safespottable. Forms 1 and 2 can be safespotted with some additional setup. Lower level players and Hardcore Ironmen may wish to utilize these methods. See quest guide for more detail."},{"id":"quest-dwarf-cannon","preparation":[],"notes":"You should be at the step to bring the ammo mould and Nulodion's notes to Captain Lawgof to complete the quest. Completion of this quest allows the use of the dwarf multicannon and smithing of cannonballs ."},{"id":"quest-merlins-crystal","preparation":[],"notes":"While in Port Sarim visit The Rusty Anchor for Alfred Grimhand's Barcrawl ."},{"id":"quest-holy-grail","preparation":[],"notes":"For the Entrana step: Purchase 11 buckets of sand from Trader Stan's Trading Post on the southernmost dock in Port Sarim . Either purchase 11 seaweed from the same shop, or pick up 11 pieces of seaweed in the north-western corner of Entrana. Pick up the glassblowing pipe from Fritz the Glassblower 's house on Entrana. Use all of the seaweed on the cooking range to create soda ash . Use all of the soda ash on the furnace to the east to create molten glass . Use the glassblowing pipe on one piece of glass to create a candle lantern , a light source to be used in future quests that take you to the Lumbridge Swamp Caves . You can light it with the black candle you got from Merlin's Crystal . Save the remaining molten glass for use in the Observatory Quest , Horror from the Deep , Wanted! , Desert Treasure I and The Fremennik Exiles . Bring a spade with you to Galahad . After talking to him, enter McGrubor's Wood to dig up 3 red vine worms for Fishing Contest , Fairytale I - Growing Pains and Wanted! . When travelling to Draynor Manor : Take your garlic , stake , and hammer to the basement of the manor to kill Count Draynor and complete Vampyre Slayer . When travelling to Karamja for the Fisher Realm step: Travel from Port Sarim to Musa Point . Visit the Karamja Spirits Bar for Alfred Grimhand's Barcrawl . On the way to Brimhaven , enter the Karamja Dungeon and then enter the Fight Caves for an easy Karamja Diary step. Continue onwards to Brimhaven and visit the Dead Man's Chest for Alfred Grimhand's Barcrawl . Travel to Ardougne and back at the port for another easy Karamja Diary step. While heading to the gold mine to get to the Fisher Realm, use the rope swing to travel to the western island and back for another easy Karamja Diary step. The Black Knight Titan has very good Ranged and Magic defence, so attack with a melee weapon and quickly move away from the Titan and you will not be hit. You may also now use the antique lamp you have been holding since completing the easy Ardougne diary on Prayer Prayer"},{"id":"quest-vampyre-slayer","preparation":[],"notes":"Complete during Holy Grail ."},{"id":"quest-the-ides-of-milk","preparation":[],"notes":"After finishing the quest, talk to Gillie Groats again to receive extra rewards. Use the magic lamp on Prayer ."},{"id":"quest-mudfoots-big-adventure","preparation":[],"notes":"Use all four lamps on Prayer ."},{"id":"quest-below-ice-mountain","preparation":[],"notes":"Black Knights' Fortress can be completed during this quest. While in Falador , start Black Knights' Fortress by talking to Sir Amik Varze on the 2 nd floor [ UK ] 3 rd floor [ US ] of the White Knights' Castle 's western tower. While in the Rising Sun Inn in Falador complete the Alfred Grimhand's Barcrawl step. Get a haircut from the Falador hairdresser next door for an easy Falador Diary task. Take a bucket and fill it with water from the pump by the hairdressers for another easy Falador Diary task. While in the Blue Moon Inn in Varrock complete the Alfred Grimhand's Barcrawl step. Pick a cabbage south of the inn and purchase an iron chainbody from Horvik's Armour Shop for Black Knights' Fortress . While in Barbarian Village , bring two soft clay to use on the potter's wheel to create two unfired bowls . One is required for Dragon Slayer I ; use the other one on the pottery oven for an easy Varrock Diary task. Purchase a bronze med helm from the Barbarian Village Helmet Shop for Black Knights' Fortress . Purchase a second for Mourning's End Part II 's item list . On your way back to Ice Mountain for the final step, bring food and go to the Black Knights' Fortress and complete that section of the Black Knights' Fortress quest. After completing Below Ice Mountain , return to Sir Amik Varze to complete Black Knights' Fortress ."},{"id":"quest-black-knights-fortress","preparation":[],"notes":"Complete during Below Ice Mountain . Use both lamps on Prayer Prayer ."},{"id":"quest-pirates-treasure","preparation":[],"notes":"You should be at the final step to complete the quest in Falador Park . While there, kill a duck with a ranged weapon or magic for an easy Falador diary task. Keep the gold ring for Mourning's End Part II 's item list , and the emerald for Legends' Quest ."},{"id":"quest-observatory-quest","preparation":[],"notes":"This quest has 12 variations of random rewards, which may include 875 experience in either Attack Attack , Strength Strength , or Defence Defence . Note: If you are level 1 in a specific combat style, you will not be assigned a constellation that gives experience in that combat skill. Visit the Dragon Inn in Yanille for Alfred Grimhand's Barcrawl . While there, buy a greenman's ale , then pick up 2 rotten tomatoes from Pelters' Veg Stall for Recipe for Disaster/Another Cook's Quest and Mourning's End Part II 's item list . Purchase 8 pots at Frenita's Cookery Shop for Rag and Bone Man I . Pick up the superantipoison (1) every time you walk past it (so that you have about a full vial); it will be very useful for Scorpion Catcher . After completion of this quest, use a silver bar and sickle mould at a furnace in Ardougne to craft a silver sickle for Nature Spirit ."},{"id":"quest-a-ruff-situation","preparation":[],"notes":"Allows raising of puppies ."},{"id":"quest-romeo-juliet","preparation":[],"notes":"Gather extra cadava berries for Making Friends with My Arm . While there, pick at least 6 redberries from the nearby redberry bush . 6 is the minimum to complete all quests (assuming you purchase red dye from Dyes to Die For later instead of using redberries to create them). Consider getting 6-8 extra as you have a chance to burn redberry pie (world hop to restock the bushes). Use the lamp on Herblore Herblore ."},{"id":"quest-priest-in-peril","preparation":[],"notes":"Allows access to Morytania . On your way to the Paterdomus Temple : Visit the Jolly Boar Inn west of the Lumber yard for Alfred Grimhand's Barcrawl . Talk to the Odd Old Man at the mine west of the temple to start Rag and Bone Man I ."},{"id":"quest-nature-spirit","preparation":["Partially complete: Rag and Bone Man I · Start during Priest in Peril , but collect the bones during the following quests when recommended by the guide."],"notes":"You will need a ghostspeak amulet and a silver sickle . Before visiting the Nature Grotto , stop at Canifis : Bank all of the pies given by Drezel. The pie dishes will be used for future quests. Purchase 20-30 raw trout from Rufus' Meat Emporium for Death Plateau (10 cooked trout are needed, 54% chance to burn at Cooking 15 Cooking ). Purchase a bag of salt from Mazchna for Icthlarin's Little Helper . After completion of this quest, restore your prayer points at the altar of nature in the Nature Grotto to complete an easy Morytania Diary task."},{"id":"quest-recruitment-drive","preparation":[],"notes":"Requires an empty inventory."},{"id":"quest-alfred-grimhands-barcrawl","preparation":[],"notes":"You should now have visited all of the required bars. Return to the Barbarian Guard at the gate to the east of the Barbarian Assault building with the barcrawl card to complete the miniquest. Allows use of the Barbarian Outpost Agility Course , which is required for Scorpion Catcher and Horror from the Deep ."},{"id":"quest-scorpion-catcher","preparation":["Unlock: Anti-dragon shield · Before starting Scorpion Catcher , partial completion of Dragon Slayer I will unlock the Anti-dragon shield to make this quest safer by protecting you from dragonfire in the Taverley Dungeon step. To collect the shield: Start the quest by speaking to the Guildmaster at the Champions' Guild south of Varrock . You may also jump over the fence to the south-east to complete an easy Varrock Diary task. Talk to Oziach in Edgeville . Return to the Guildmaster and ask him all the questions . Talk to Duke Horacio on the 1 st floor [ UK ] 2 nd floor [ US ] of Lumbridge Castle to receive the shield."],"notes":"While at the Sorcerer's Tower complete the following Rag and Bone Man I tasks: At the sheep pen south-west of the tower, kill a ram and pick up the ram skull . At the mine south of the tower, kill a grizzly bear and pick up the bear ribs . Also pick up the bear fur for Mourning's End Part I . By Keep Le Faye east of the tower, kill a giant bat and pick up the giant bat wing . On your way to the Taverley Dungeon , cross the crumbling wall in western Falador for an easy Falador Diary task."},{"id":"quest-jungle-potion","preparation":[],"notes":"Optional: Bring a small fishing net to catch stackable raw karambwanji for your kitten. You will need to train to 5 Fishing beforehand. (First herb) Collect two extra grimy snake weed , one for Zogre Flesh Eaters and another for Legends' Quest . (Second herb) Collect one extra ardrigal for Legends' Quest . (Fourth herb) Collect an extra grimy volencia moss for Fairytale I . Kill a Jogre in the Pothole Dungeon while collecting the moss for an easy Karamja Diary task. Kill a nearby monkey and pick up the monkey paw for Rag and Bone Man I . (Fifth herb) Collect an extra grimy rogue's purse for Zogre Flesh Eaters . After completion of this quest: Purchase 15 breads from Jiminua's Jungle Store south of Brimhaven for Death Plateau , Enakhra's Lament , and two Recipe for Disaster subquests. Collect five seaweed from the west coast for an easy Karamja Diary task."},{"id":"quest-a-porcine-of-interest","preparation":[],"notes":"While talking to Sarah , buy 10 empty sacks for Enlightened Journey and Mourning's End Part II 's item list . Pick 20 potatoes from the potato field to the east of Draynor Village and fill 2 sacks with them for Enlightened Journey and Mourning's End Part II 's item list . After completion of this quest in Draynor Village , perform the following Rag and Bone Man I tasks: Buy 8 jugs of vinegar from the Wine Shop and use them on your 8 pots to create pots of vinegar for Rag and Bone Man I . Kill a level 2 goblin south of the village and pick up the goblin skull . Kill a unicorn in the swamp and pick up the unicorn bone . Keep the unicorn horn for Ratcatchers . Kill a giant rat in the swamp and pick up the giant rat bone . Kill a big frog in the swamp and pick up the big frog leg . While in the swamp, collect 6 swamp tar for Cold War , Eagles' Peak , Forgettable Tale... , Horror from the Deep , Tears of Guthix and Troll Romance ."},{"id":"quest-rag-and-bone-man-i","preparation":[],"notes":"You should now have all of the bones required to complete the quest. After completion of this quest Rag and Bone Man II will automatically start."},{"id":"quest-death-plateau","preparation":["Partially complete: Rag and Bone Man II · Pick up the bones during future quests. Note that completion of this quest will take a very long time, and you will not immediately have the requirements to collect every bone, with the highest requirement being 40 Slayer Slayer . You can begin by killing bats near the Odd Old Man until you obtain a bat wing ."],"notes":"You'll need an iron bar , which you cannot smith yet. There is an iron bar spawn north-west of the Ferox Enclave accessible via a Clan Wars minigame teleport, and one at the Sunset Coast south of Civitas illa Fortis . They are also a drop from Paladins in Ardougne (safespottable) at a rate of 1/14.22 or from the White Knights in Falador at a rate of 1/16. Pick up two additional bars for The Knight's Sword ."},{"id":"quest-the-queen-of-thieves","preparation":[],"notes":"A stew is required, which was received as a quest reward from Gertrude's Cat or can be bought from Forester's Arms in Seers' Village for 20 coins. Kill seagulls on the southern docks until they drop a seagull wing for Rag and Bone Man II . While in The Warrens , trade the shopkeeper in the Warrens General Store to complete an easy Kourend & Kebos Diary task. After the Conrad King step, from Frankie's Fishing Emporium purchase three raw cod for Freeing Pirate Pete , a raw shark for The Fremennik Trials and a raw swordfish for the Ardougne medium diary Swordchick ."},{"id":"quest-the-forsaken-tower","preparation":[],"notes":""},{"id":"quest-the-depths-of-despair","preparation":[],"notes":"Bring a spade to mine some Saltpetre for an easy Kourend & Kebos Diary task on your way to the cave. Kill a sand crab whilst in the crab claw caves for an easy Kourend & Kebos Diary task. Steal a fruit from the Fruit Stall to the north for an easy Kourend & Kebos Diary task after completing the quest."},{"id":"quest-tale-of-the-righteous","preparation":[],"notes":""},{"id":"quest-the-ascent-of-arceuus","preparation":[],"notes":""},{"id":"quest-the-writings-on-the-wall","preparation":[],"notes":""},{"id":"quest-the-grand-tree","preparation":[],"notes":"Allows use of the gnome glider transportation system. Before starting the quest, kill terrorbirds to the south-west of the Grand Tree until they drop a terrorbird wing for Rag and Bone Man II . While in the Grand Tree , buy a gnome spice and an orange for Recipe for Disaster/Freeing the Goblin generals at the Grand Tree Groceries . Buy 3 vodkas from Heckel Funch on the east side of the 1 st floor [ UK ] 2 nd floor [ US ] (east of the pub): 2 for Bone Voyage and 1 for Eadgar's Ruse . When on Karamja , kill Jogres by the Gnome glider west of the Ship Yard until you obtain a Jogre bone for Rag and Bone Man II . Keep the Jogre Bones for Tai Bwo Wannai Trio . After completion of this quest, start Making History by talking to Jorral at The Outpost south-west of the Tree Gnome Stronghold ."},{"id":"quest-mountain-daughter","preparation":[],"notes":"Before starting the quest: Use the minigame teleport to Barbarian Assault . Take out two planks , 60 steel nails , a hammer and some food and cross the basalt rock to the north. Start Horror from the Deep by talking to Larrissa outside the Lighthouse . Head east and use two planks to fix the bridge for Horror from the Deep . Stop at Rellekka to complete that section of Making History . Head east past Rellekka , and kill bunnies by the swaying tree until you obtain a rabbit bone . Start The Giant Dwarf in the cave north-west of the camp to unlock the trapdoor shortcut from Grand Exchange and Blast Furnace minigame teleport . Completing the cutscene and conversation with Commander Veldaban unlocks it. While in Keldagrim , buy the following from Gunslik's Assorted Items : Charcoal for The Dig Site (you may consider purchasing 4 more for future quests). Pestle and mortar if you don't have one for The Dig Site . 4 vials for The Dig Site , The Golem , The Hand in the Sand and Land of the Goblins . 2 ropes for The Dig Site . Chisel for The Golem . Retrieve the quest items and combat gear, then leave the area by talking to the Dwarven Boatman north-east of the river. You can now head to the quest area."},{"id":"quest-shield-of-arrav","preparation":[],"notes":"The chat channel for finding a partner is 'osrs soa'. Use the lamp on Herblore Herblore ."},{"id":"quest-the-dig-site","preparation":[],"notes":"Before beginning this quest, start The Golem in the Ruins of Uzer and complete that section of the quest. Both quests will require you to visit the Digsite and then the Varrock Museum , so complete those two steps together. On your way to the digsite, take a pickaxe and mine an iron ore from the South-east Varrock mine for an easy Varrock Diary task. After completion of this quest, return the level 3 certificate to Curator Haig Halen at the Varrock Museum for a fruit blast which can be used in Recipe for Disaster: Another Cook's Quest ."},{"id":"quest-the-golem","preparation":[],"notes":"You should be at the final step of this quest to return to the Ruins of Uzer . On the way, visit the Al Kharid mine and mine 12 coal for Elemental Workshop I and Elemental Workshop II , and 1 iron ore for an easy Lumbridge & Draynor Diary task. Start Prince Ali Rescue while passing through Al Kharid by talking to Chancellor Hassan , then Osman . Bring a bird snare , pickaxe , hammer , chisel and knife . While in the Shantay Pass , purchase a full set of desert clothing and an empty waterskin . Equip it when passing through the pass to for an easy Desert Diary task. On the way to Uzer use your knife on a Kharidian cactus for an easy Desert Diary task. When stealing the feather from the Desert phoenix , mine five clay nearby for another easy Desert Diary task. Use the bird snare to catch a nearby golden warbler for another easy Desert Diary task. Use the hammer and chisel to collect two sapphires , two rubies and two emeralds from the throne in the throne room. One sapphire is required for Tears of Guthix and Making History respectively."},{"id":"quest-ethically-acquired-antiquities","preparation":[],"notes":"Travel to Varlamore for this quest via Regulus Cento at Varrock 's eastern entrance. While in Civitas illa Fortis buy an iron spear from the Fortis Blacksmith for Tai Bwo Wannai Trio ."},{"id":"quest-twilights-promise","preparation":[],"notes":"After the quest, use the Quetzal Transport System to travel to Tal Teklan . At the Dyes to Die For shop purchase the following dyes for future quests. Consider buying a few extra dyes of each colour for safety. The purchase list assumes blue dye is used for Freeing the Goblin generals and 3x yellow/red/blue are used for Ghosts Ahoy . 7 blue dyes 2 orange dyes 8 yellow dyes 8 red dyes 1 green dye 2 purple dyes Purchase an oak longbow from Arcuani's Archery Supplies for Ghosts Ahoy ."},{"id":"quest-death-on-the-isle","preparation":[],"notes":"After the quest, make sure to claim your costume needle, which doesn't require thread to craft, from the costumer down in the cellar out back."},{"id":"quest-recipe-for-disaster-another-cooks-quest","preparation":[],"notes":""},{"id":"quest-goblin-diplomacy","preparation":[],"notes":""},{"id":"quest-the-lost-tribe","preparation":[],"notes":"Allows access to Nardok's Bone Weapons where players can purchase the Dorgeshuun crossbow and bone bolts for early Ranged training. After completion of this quest, talk to Mistag to start Death to the Dorgeshuun . Kill cave goblins until they drop a cave goblin skull for Rag and Bone Man II . Keep the ring of life quest reward for The Curse of Arrav if you do not plan to obtain more."},{"id":"quest-death-to-the-dorgeshuun","preparation":[],"notes":"Make sure to keep a set of polished buttons from H.A.M. members for Animal Magnetism later. Kill a Cave bug during the quest while travelling underground for an easy Lumbridge & Draynor Diary task. After completion of this quest: Enter Dorgesh-Kaan south of Mistag . At Miltog's Lamps in the central part of the Dorgesh-Kaan marketplace, purchase a bullseye lantern (empty) . Use swamp tar on the nearby lamp still to fill it and use the empty lantern on the still to fill it with oil. Use a sapphire on the bullseye lantern to create a sapphire lantern . The sapphire lantern is required to complete Tears of Guthix . Consider completing this quest earlier if you have 49 Firemaking as it unlocks a useful weekly minigame for gathering experience in your lowest skill."},{"id":"quest-recipe-for-disaster-freeing-the-goblin-generals","preparation":[],"notes":"Use blue dye on the orange slices . Completing this quest unlocks access to the second tier of the Culinaromancer's Chest . Purchase the following from it (hop worlds to refresh stock): 7 buckets of milk for Ghosts Ahoy , A Tail of Two Cats , Ratcatchers , Recipe for Disaster (three subquests), and Mourning's End Part II 's item list . 7 pots of flour for Prince Ali Rescue , Recipe for Disaster (two subquests), The Knight's Sword , The Giant Dwarf , Prying Times , and Mourning's End Part II 's item list . 3 eggs for Recipe for Disaster (two subquests) and Mourning's End Part II 's item list . 3 cake tins for Recipe for Disaster (one subquest), Troll Romance and Mourning's End Part II 's item list . Grapes for Monkey Madness II . Pot of cream for Recipe for Disaster (one subquest). Spice for Desert Treasure I . Create 3 redberry pies for The Knight's Sword , The Giant Dwarf and Prying Times while in the cellar: Use a pot of flour on a bucket of water (a bucket spawns in the cellar and can be filled at the nearby sink) to create pastry dough . Use the pastry dough on a pie dish to create a pie shell . Use redberries on the pie shell to create an uncooked berry pie . Cook the uncooked berry pie on the kitchen range. If you fail to cook it, repeat the steps (purchase more flour as necessary). The burnt pie can be emptied to reclaim the pie dish. If you run out of redberries, you can purchase more from the Port Sarim Food Store and cook the pie nearby."},{"id":"quest-the-knights-sword","preparation":[],"notes":"On the way to Thurgo , mine 16 iron ore at the Rimmington Mine for future quests to be used in iron bars . Note that you won't have the required Smithing level for the two iron bars required for this quest - you can obtain those from spawns if you haven't already. Mine an extra blurite ore for the easy Falador Diary . Completion of this quest grants you the Smithing level required to smith iron bars. Smelt both the iron ore and the blurite ore you have gathered at the Falador furnace ."},{"id":"quest-prince-ali-rescue","preparation":[],"notes":"Speak to Osman after completing the quest and ask him if there is anything you can help with to unlock the Sorceress's Garden Minigame Teleport ."},{"id":"quest-the-feud","preparation":[],"notes":"While in Pollnivneach , collect 3 buckets of Ugthanki dung for My Arm's Big Adventure , and 1 extra bucket for Forgettable Tale... before you return to Al Kharid to complete The Feud ."},{"id":"quest-the-corsair-curse","preparation":[],"notes":""},{"id":"quest-icthlarins-little-helper","preparation":[],"notes":"Train to 30 Woodcutting for the willow log required for this quest, and obtain a second one for Enakhra's Lament . When obtaining a bucket of sap , get a second one for The Eyes of Glouphrie . It is possible to obtain an agility potion(4) from the Possessed Priest at the end of the quest, which may be saved for use in Tai Bwo Wannai Trio ."},{"id":"quest-shadow-of-the-storm","preparation":[],"notes":"Flinch the quest boss with melee to avoid taking damage. For the black clothing required in the quest, you should have the black wizard hat and priest gown set. Use the experience reward on Ranged Ranged ."},{"id":"quest-sea-slug","preparation":[],"notes":"Complete a medium task for the Ardougne diary by fishing on the platform. You can buy a small fishing net from a shop near the quest start in Witchaven ."},{"id":"quest-fishing-contest","preparation":[],"notes":""},{"id":"quest-recipe-for-disaster-freeing-the-mountain-dwarf","preparation":[],"notes":"When talking to Kaylee in the Falador pub, purchase a Wizard's mind bomb for Dragon Slayer I ."},{"id":"quest-the-ribbiting-tale-of-a-lily-pad-labour-dispute","preparation":[],"notes":""},{"id":"quest-lost-city","preparation":[],"notes":"Cut a second dramen branch for Recipe for Disaster/Freeing Sir Amik Varze , and optionally a third one to make a step in The Fremennik Trials easier. Do not turn them into dramen staffs . You may get a zombie bone while trying to get a bronze axe from the zombies . Grants the ability to make cosmic runes and to use the dragon dagger and the dragon longsword ."},{"id":"quest-fairytale-i-growing-pains","preparation":[],"notes":"There is a small chance you may need either Fishing 28 Fishing or Fishing 38 Fishing to obtain a raw slimy eel or raw cave eel , respectively."},{"id":"quest-ratcatchers","preparation":["Partially complete: Fairytale II - Cure a Queen · Continue with this quest until you unlock fairy rings ."],"notes":"The rat poison required for this quest can be obtained from the Clock Tower dungeon if you didn't pick up an extra one during Clock Tower . Making it yourself is not required to complete the quest. When in the Varrock Sewers , complete the following Rag and Bone Man II tasks: Kill rats until you obtain a rat bone . Kill zombies until you obtain a zombie bone . After completing this quest you can start growing your adult cat into a wily cat, which is the best cat for catching hellrats."},{"id":"quest-recipe-for-disaster-freeing-evil-dave","preparation":[],"notes":"Gain access to spicy stews during the quest, which can be useful for boosting stats. The 9 required stews can be obtained from The Cloak and Stagger in Shayzien . Ensure you have raised a kitten into a cat first before completing this quest and the following quest Ratcatchers ."},{"id":"quest-ghosts-ahoy","preparation":[],"notes":"This quest unlocks the ectophial for an unlimited teleport to the Ectofuntus , and gives free access to Port Phasmatys . When gathering the ecto-tokens , get an additional 20 for Animal Magnetism . Make an additional Nettle tea for Skippy and the Mogres . While in Port Phasmatys , create a sapphire amulet by using a gold bar on the nearby furnace while also carrying a cut sapphire and an amulet mould , then string it with a ball of wool . Talk to Droalak for Making History , then give the sapphire amulet to Melina east of the general store. Return to Drolak to receive a scroll ."},{"id":"quest-creature-of-fenkenstrain","preparation":[],"notes":"Before beginning the quest, create 7 bronze wire on an anvil . 3 will be used for this quest, and the remaining 4 are for Recipe for Disaster/Freeing Pirate Pete and Shilo Village . While in the experiment cave , kill experiments until you obtain an experiment bone for Rag and Bone Man II ."},{"id":"quest-shades-of-mortton","preparation":[],"notes":"It is recommended to make several doses of serum 208 to use on Razmire Keelgan to gain access to the building supplies store, or on the afflicted villagers to receive drops. (See \"Cure rewards\" under Serum 208 .) Once done, purchase 11 swamp paste from the Mort'ton Builder's Store for The Slug Menace , Dragon Slayer II , and Mourning's End Part II 's item list . After the quest bring the diary of Herbi Flax to the Apothecary in Varrock for 335 Herblore experience."},{"id":"quest-making-history","preparation":[],"notes":"You should have completed the Rellekka and Port Phasmatys steps of this quest. Complete the silver merchant step and then finish the quest by returning to Jorral with the journal and scroll ."},{"id":"quest-temple-of-ikov","preparation":[],"notes":"Equip the ice arrows obtained during the quest alongside darts or throwing knives to avoid needing a yew shortbow (which would require 40 Ranged ). Both black knives and black darts are a common drop from Burthorpe soldiers . Alternatively to killing soldiers, you can purchase steel knives from Martin Thwait's Lost and Found. if you have 50 Agility and Thieving . Pray Protect from Magic when fighting the Fire Warrior of Lesarkus . The 20 required limpwurt roots can be obtained as drops from hobgoblins or hill giants . Side with the Guardians of Armadyl for the Armadyl pendant for cheap God Wars Dungeon protection."},{"id":"quest-the-birds-and-the-wasps","preparation":["Unlock: Varrock Museum Kudos · Talk to Historian Minas just up the stairs and tell him the information about the displays to get the kudos and three antique lamps from the quests you have done. Use them on Herblore Herblore . Complete the cleaning finds part of the Varrock Museum to earn another 50 kudos . Combining these 50 kudos, the 28 kudos from the Natural History Quiz , and the 50 kudos from Historian Minas, this should put you at 128 kudos in total. Finally, talk to the information clerk to claim Mining 3,500 Mining and Crafting 2,500 Crafting experience."],"notes":""},{"id":"quest-bone-voyage","preparation":[],"notes":"This quest requires you to earn 100 kudos from the Varrock museum , which you should have from the last step. Group ironmen with a party member with at least level 25 Construction (boostable) can now start doing birdhouse runs . Other ironmen can get level 23 Construction now to start doing the runs (boost with tea), or wait for The Fremennik Isles . Marrentill can be dropped by chaos druids in Taverley Dungeon ."},{"id":"quest-the-tourist-trap","preparation":[],"notes":"Choose Agility Agility for both experience rewards. The boss can be safespotted by talking to a guard and using said guard as an object to hide behind."},{"id":"quest-wanted","preparation":[],"notes":"While in the Taverley Dungeon , kill Baby blue dragons until you obtain a Baby dragon bone for Rag and Bone Man II . Keep 1 Babydragon bones for Mourning's End Part II 's item list ."},{"id":"quest-ernest-the-chicken","preparation":[],"notes":"Prepare quest items for Animal Magnetism as well before heading to Draynor Manor . Use the lamp on Herblore Herblore ."},{"id":"quest-animal-magnetism","preparation":[],"notes":"A Holy Symbol can be blessed by the monk in the monastery near Edgeville. A mithril axe can be bought from Lunami's Axe Shop in Auburnvale . While in Alice 's cow pen, kill undead cows until you obtain undead cow ribs for Rag and Bone Man II ."},{"id":"quest-imp-catcher","preparation":["Easy Karamja Diary · Use the on Herblore Herblore . If you followed the guide closely, you should be at the last steps to mine some gold from the rocks north of Brimhaven , and cross Cairn Isle ."],"notes":"Camp the spawns of imps on the east side of the Ardougne Monastery or in a basement in Kastori for beads. They also drop mind talismans which you should keep for the easy Falador Diary ."},{"id":"quest-watchtower","preparation":[],"notes":""},{"id":"quest-the-giant-dwarf","preparation":[],"notes":"Join the Purple Pewter while wearing a full set of H.A.M. robes for a 20 point head start during the Consortium section of the quest. Purchase a steel warhammer at Vigr's Warhammers while in Keldagrim for In Search of the Myreque . Steal from the baker's stall on the eastern side of the Keldagrim Palace to complete an easy Fremennik Diary task. Browse the Stonemason shop just south of the bank to complete an easy Fremennik Diary task."},{"id":"quest-forgettable-tale","preparation":[],"notes":"If you don't intend to brew more, save 1 dwarven stout (m) from the Quest Reward to boost for Making Friends with My Arm ."},{"id":"quest-big-chompy-bird-hunting","preparation":[],"notes":"Completion of this quest allows you to make ogre arrows . While in the Feldip Hills , kill wolves and ogres until you obtain a wolf bone and ogre ribs for Rag and Bone Man II . Head south-west of the glider and pick up the skull found on the coast for Mourning's End Part II 's item list . Keep the Ogre bow for Recipe for Disaster/Freeing Skrach Uglogwee ."},{"id":"quest-zogre-flesh-eaters","preparation":[],"notes":"Keep the black prism to exchange for 5,000 after completing Shilo Village later. Kill Zogres until you obtain a Zogre bone for Rag and Bone Man II ."},{"id":"quest-another-slice-of-h-a-m","preparation":["Easy Varrock Diary · Use the on Herblore Herblore .","Easy Desert Diary · Use the on Herblore Herblore . Keep a potato cactus for Mourning's End Part II 's item list ."],"notes":"If you already have a mind talisman , craft a tiara and bring both with you during the Goblin Village step of this quest to craft a mind tiara at the nearby Mind Altar for an easy Falador Diary task. The ancient mace is cheap protection for the God Wars Dungeon ."},{"id":"quest-spirits-of-the-elid","preparation":[],"notes":"Bring 10-15 ice coolers to the Water Ravine Dungeon step, and kill level 42 lizards south of the dungeon until they drop a desert lizard bone for Rag and Bone Man II (drop rate is 1/4). When heading to the genie's crevice , complete the following Rag and Bone Man II tasks: Kill jackals outside the crevice until they drop a jackal bone . Inside the crevice, kill desert snakes until they drop a snake spine . South-west of the crevice, kill vultures until they drop a vulture wing ."},{"id":"quest-dragon-slayer-i","preparation":[],"notes":"Starting this quest unlocks dragon tasks for Slayer . While in the Port Sarim jail , talk to the Security Guard on the 1 st floor [ UK ] 2 nd floor [ US ] to receive a Security book for the easy Falador Diary . Completing this quest allows you to use green d'hide body , rune platebody and dragon platebody ."},{"id":"quest-horror-from-the-deep","preparation":[],"notes":"Completing this quest allows you to buy God books. The book of war is cheap protection for the God Wars Dungeon . After completion of this quest, kill Dagannoth in the Lighthouse dungeon until you obtain Dagannoth ribs for Rag and Bone Man II ."},{"id":"quest-the-garden-of-death","preparation":[],"notes":""},{"id":"quest-enlightened-journey","preparation":[],"notes":"Allows use of the balloon transport system . If the 12 willow branches are obtained from planting Auguste's sapling , you will need to wait 4 hours for the willow tree to grow and then 5 more minutes per branch after checking its health. It may be more desirable to grow your own willow tree before even starting the quest. If you're growing your own willow tree during this quest, you should obtain an extra 6 willow branches so that you may complete the medium Falador Diary task of crafting a basket on the Falador farm loom ."},{"id":"quest-garden-of-tranquillity","preparation":["Unlock: Balloon transport system to Crafting Guild · Requires 10 oak logs ."],"notes":"You can use a hammer on some essence and grind the essence shards into dust before starting the quest to save yourself some space. After completion, wait up to 5 minutes and pick up a white tree fruit for a medium Varrock Diary task."},{"id":"quest-in-search-of-the-myreque","preparation":[],"notes":"Before starting the quest, complete the following Rag and Bone Man II tasks: Kill werewolves in Canifis until you obtain a werewolf bone . Kill ghouls west of Canifis until you obtain a ghoul bone ."},{"id":"quest-in-aid-of-the-myreque","preparation":[],"notes":"A good tip for lower levels: Using Efaritay's aid allows you to use weapons other than the silver sickle when equipped. A mithril bar is needed for this quest. One can be easily obtained by killing chaos dwarves in Taverley Dungeon ."},{"id":"quest-darkness-of-hallowvale","preparation":[],"notes":"Use all three experience rewards on Herblore Herblore ."},{"id":"quest-a-tail-of-two-cats","preparation":[],"notes":"You should have the chocolate cake from Gertrude's Cat for this quest. Alternatively, chocolate slices may be stolen from the Ardougne Baker's Stall. and combined to make a chocolate cake. Use on Herblore Herblore ."},{"id":"quest-tower-of-life","preparation":[],"notes":""},{"id":"quest-tai-bwo-wannai-trio","preparation":["Easy Falador Diary · Use the on Herblore Herblore ."],"notes":"Warning: If the one raw karambwan obtained during the quest is burned, 65 Fishing is required to fish more and continue the quest. You must return to the brothers after completing the quest to claim all experience rewards. An Agility potion(4) is needed for the quest so 2 toadflax are required if you're making the potion yourself. You can acquire toadflax from the Brimhaven Agility Arena for 3 vouchers each if you lack the Farming level/seeds required to grow them. You can alternatively obtain the potion from the Jekyll and Hyde random event by giving an irit leaf . While near Brimhaven , enter the Brimhaven Dungeon and kill Moss giants and Fire giants until you obtain a Moss giant bone and Fire giant bone for Rag and Bone Man II . While near Tai Bwo Wannai , get 100% favour in the Tai Bwo Wannai Cleanup minigame for a medium Karamja Diary task. This will also satisfy the 60% favour requirement for My Arm's Big Adventure ; it's best to get 100% now for the diary task, as that quest consumes the 60% favour."},{"id":"quest-troll-stronghold","preparation":[],"notes":"Grants the ability to make law runes . Kill Mountain trolls by the Troll Stronghold entrance until you obtain a troll bone for Rag and Bone Man II ."},{"id":"quest-eadgars-ruse","preparation":[],"notes":"Pick up two extra goutweed herbs from the storage for use in Dream Mentor and Dragon Slayer II ."},{"id":"quest-my-arms-big-adventure","preparation":[],"notes":""},{"id":"quest-the-fremennik-trials","preparation":[],"notes":""},{"id":"quest-shilo-village","preparation":[],"notes":"After completing the quest, you can sell every item you obtained during the quest to Yanni Salika in Shilo Village for 2,000 — 100 each for the stone-plaque , tattered scroll , crumpled scroll , Bervirius notes and the bone key , 500 for the locating crystal , and 1000 for the Beads of the Dead . If you kept the black prism from Zogre Flesh Eaters , you can exchange it for 5,000 ."},{"id":"quest-troll-romance","preparation":[],"notes":"Arrg attacks with melee and ranged. He can be safespotted at the west side entrance of the arena."},{"id":"quest-the-eyes-of-glouphrie","preparation":[],"notes":"Requires a mud rune for completion which can be obtained from the Mage Training Arena shop. If crafting the rune yourself, you will need to obtain a water talisman and an earth talisman from water wizards and earth wizards respectively. If you have not already, kill terrorbirds to the south-west of the Grand Tree until they drop a terrorbird wing for Rag and Bone Man II ."},{"id":"quest-elemental-workshop-i","preparation":[],"notes":"Bring supplies to kill one of each elemental (level 35) to complete an easy Kandarin Diary task. Note: Earth elementals in rock form do not count. Mine 2 additional elemental ore for part II (recommended: get a third for a mind shield after the quest if you ever plan on doing elite clue scrolls )."},{"id":"quest-elemental-workshop-ii","preparation":[],"notes":"Grants the ability to make and use elemental mind equipment. Bring an extra 4 coal if you plan on making a mind shield (recommended if you plan on doing elite clue scrolls )."},{"id":"quest-prying-times","preparation":[],"notes":""},{"id":"quest-sleeping-giants","preparation":[],"notes":"Unlocks Giants' Foundry ."},{"id":"quest-recipe-for-disaster-freeing-pirate-pete","preparation":[],"notes":""},{"id":"quest-a-shell-of-a-friend","preparation":[],"notes":""},{"id":"quest-the-fremennik-isles","preparation":[],"notes":"Start doing birdhouse runs after this quest. Put both experience rewards on Strength Strength ."},{"id":"quest-getting-ahead","preparation":[],"notes":""},{"id":"quest-meat-and-greet","preparation":[],"notes":""},{"id":"quest-recipe-for-disaster-freeing-the-lumbridge-guide","preparation":[],"notes":""},{"id":"quest-recipe-for-disaster-freeing-skrach-uglogwee","preparation":[],"notes":""},{"id":"quest-haunted-mine","preparation":[],"notes":"Alternatively, this quest can be left until you have 60+ combat stats as this quest has a difficult boss and unlocks no others."},{"id":"quest-contact","preparation":[],"notes":"Use on Magic Magic twice."},{"id":"quest-monkey-madness-i","preparation":[],"notes":"Get four additional Monkey talismans from the Monkey child by telling him you have lost the talisman. After world hopping, he will give you another one. Before returning to Zooknock in the Ape Atoll Dungeon , kill a Monkey Guard , Monkey Archer and Monkey Zombie and pick up their bones. Create three additional greegrees from Zooknock , which are required for Recipe for Disaster/Freeing King Awowogei . The fourth monkey talisman will be used for Monkey Madness II , but you cannot craft this greegree yet. After quest completion, talk to Daero for 35,000 experience in Attack Attack and Defence Defence and 20,000 experience in Strength Strength and Hitpoints Hitpoints ."},{"id":"quest-olafs-quest","preparation":["Unlock: Balloon transport system to Varrock · Requires 10 willow logs ."],"notes":""},{"id":"quest-tears-of-guthix","preparation":[],"notes":"Also allows access to the Tears of Guthix minigame, which provides experience in your lowest skill."},{"id":"quest-one-small-favour","preparation":[],"notes":"Use on Herblore Herblore ."},{"id":"quest-the-slug-menace","preparation":[],"notes":""},{"id":"quest-between-a-rock","preparation":[],"notes":""},{"id":"quest-cold-war","preparation":[],"notes":"While training Construction , consider building a workshop and crafting table 3 in your PoH to save time for this quest."},{"id":"quest-underground-pass","preparation":[],"notes":"Disciples of Iban always drop Zamorak robes . Stock up now as they will no longer be there after you complete the quest. Cheap protection for the God Wars Dungeon ."},{"id":"quest-skippy-and-the-mogres","preparation":[],"notes":"Kill Mogres until they drop a Mogre bone for Rag and Bone Man II . Head north to the Asgarnian Ice Dungeon and kill Ice giants until they drop ice giant ribs for the same quest."},{"id":"quest-rag-and-bone-man-ii","preparation":[],"notes":"Travel to the Fremennik Slayer Dungeon with a mirror shield . Enter the dungeon and kill basilisks until you obtain a basilisk bone . You should now have all of the bones required to finish the quest."},{"id":"quest-lair-of-tarn-razorlor","preparation":[],"notes":"Kill a Terror dog for a medium Morytania Diary task."},{"id":"quest-current-affairs","preparation":[],"notes":""},{"id":"quest-crab-quest","preparation":[],"notes":""},{"id":"quest-rum-deal","preparation":[],"notes":""},{"id":"quest-cabin-fever","preparation":[],"notes":""},{"id":"quest-his-faithful-servants","preparation":[],"notes":"Provides a large amount of Prayer experience. The melee Barrows brothers can be kited in their sarcophagus room."},{"id":"quest-the-great-brain-robbery","preparation":[],"notes":"Use on Herblore Herblore ."},{"id":"quest-scrambled","preparation":[],"notes":""},{"id":"quest-the-hand-in-the-sand","preparation":[],"notes":""},{"id":"quest-enakhras-lament","preparation":[],"notes":"Mine an additional piece of granite (any size) for King's Ransom ."},{"id":"quest-heroes-quest","preparation":[],"notes":""},{"id":"quest-throne-of-miscellania","preparation":[],"notes":""},{"id":"quest-royal-trouble","preparation":[],"notes":""},{"id":"quest-desert-treasure-i","preparation":[],"notes":"If you are lower than 75 Woodcutting or 58 Hunter and have yet to obtain magic logs , skip forward to Legends' Quest and chop dead yommi tree saplings to obtain them. Magic logs may also be obtained through hunters' rumour loot sacks from level 46 hunter."},{"id":"quest-a-taste-of-hope","preparation":[],"notes":"Use the tome of experience on Herblore Herblore ."},{"id":"quest-family-crest","preparation":[],"notes":"While en route to kill Chronozon , grab 5 red spiders' eggs from the Edgeville Wilderness Dungeon for the Wilderness Diary ."},{"id":"quest-legends-quest","preparation":[],"notes":"Use all the experience rewards on Herblore Herblore . If using yommi trees to obtain magic logs , approximately 200 seeds are needed. Use the drop trick to obtain these from Ungadulu . To prevent a return trip, grab a vanilla pod for Recipe for Disaster/Freeing Sir Amik Varze ."},{"id":"quest-recipe-for-disaster-freeing-sir-amik-varze","preparation":[],"notes":""},{"id":"quest-curse-of-the-empty-lord","preparation":[],"notes":"Talk to Historian Minas and use the antique lamp on Herblore Herblore ."},{"id":"quest-the-generals-shadow","preparation":[],"notes":"Requires the ring of visibility ."},{"id":"quest-a-new-leaf","preparation":[],"notes":"Use the lamp on Prayer Prayer ."},{"id":"quest-a-souls-bane","preparation":["All Easy Achievement Diaries · For the scarecrow task, if you don't have 47 Farming you can obtain a watermelon by boosting Farming with a garden pie purchased from the Cooks' Guild Pie Shop for 24 coins. Requires a chef's hat to enter. Use all on Herblore Herblore .","Medium Ardougne Diary · A mith grapple , which requires 59 Fletching and 59 Smithing to make, is required to complete this diary as well as the medium Falador and Kandarin diaries. An alternative is to kill certain monsters in the Ancient Cavern , which requires the Firemaking portion of the Barbarian Training miniquest. All variants of Skeletons and Barbarian spirits found in the Caverns drop the grapple at a 1/42.67 rate. These monsters also drop yew logs ; 11 are needed to complete the diary (the alternative is 60 Woodcutting ). Use on Herblore Herblore .","Medium Falador Diary"],"notes":"After completion of this quest, re-enter the dungeon to complete a medium Varrock Diary task."},{"id":"quest-land-of-the-goblins","preparation":["Medium Varrock Diary","Medium Kandarin Diary"],"notes":""},{"id":"quest-fairytale-ii-cure-a-queen","preparation":[],"notes":"Boost Farming with a garden pie purchased from the Cooks' Guild Pie Shop for 24 coins. Requires a chef's hat to enter."},{"id":"quest-a-kingdom-divided","preparation":[],"notes":"Use the antique lamp on Herblore Herblore ."},{"id":"quest-the-heart-of-darkness","preparation":[],"notes":""},{"id":"quest-perilous-moons","preparation":[],"notes":""},{"id":"quest-recipe-for-disaster-freeing-king-awowogei","preparation":[],"notes":""},{"id":"quest-regicide","preparation":[],"notes":"Pick up white berries north of the Elf Tracker for Mourning's End Part II 's item list . Make an additional barrel of naphtha (not a completed Barrel bomb ) for Mourning's End Part I ."},{"id":"quest-roving-elves","preparation":[],"notes":""},{"id":"quest-mournings-end-part-i","preparation":[],"notes":""},{"id":"quest-mournings-end-part-ii","preparation":[],"notes":"You should have most of the items for the item list . The alternative would be to obtain a catalytic talisman from Guardians of the Rift which is a 1/200 drop from the Rewards Guardian ."},{"id":"quest-lunar-diplomacy","preparation":[],"notes":""},{"id":"quest-what-lies-below","preparation":[],"notes":"After the completion of this quest, you should have enough kudos to claim 4,000 experience each in Crafting Crafting , Hunter Hunter , Prayer Prayer , Slayer Slayer and Smithing Smithing at the information clerk in the Varrock Museum ."},{"id":"quest-kings-ransom","preparation":[],"notes":"Use the antique lamp on Herblore Herblore ."},{"id":"quest-swan-song","preparation":["Knight Waves Training Grounds (miniquest)"],"notes":""},{"id":"quest-recipe-for-disaster-defeating-the-culinaromancer","preparation":[],"notes":"Use the antique lamp on Herblore Herblore ."},{"id":"quest-grim-tales","preparation":[],"notes":""},{"id":"quest-dream-mentor","preparation":[],"notes":"Use the dreamy lamp on Magic Magic ."},{"id":"quest-eagles-peak","preparation":[],"notes":""},{"id":"quest-at-first-light","preparation":[],"notes":""},{"id":"quest-defender-of-varrock","preparation":["Medium Western Provinces Diary","Medium Desert Diary"],"notes":"Speak to Historian Minas in the Varrock Museum and put the antique lamp on Herblore Herblore ."},{"id":"quest-devious-minds","preparation":["Medium Wilderness Diary · Requires level 50 Slayer .","Medium Karamja Diary · Requires Fishing 60 Fishing to boost to 65.","Medium Kourend & Kebos Diary","Medium Lumbridge & Draynor Diary","Medium Morytania Diary"],"notes":""},{"id":"quest-the-final-dawn","preparation":[],"notes":"Use the lamp on Magic Magic ."},{"id":"quest-troubled-tortugans","preparation":[],"notes":""},{"id":"quest-the-red-reef","preparation":[],"notes":""},{"id":"quest-fallen-from-grace","preparation":[],"notes":""},{"id":"quest-shadows-of-custodia","preparation":[],"notes":""},{"id":"quest-the-path-of-glouphrie","preparation":[],"notes":""},{"id":"quest-rag-and-bone-man-iii","preparation":[],"notes":""},{"id":"quest-the-fremennik-exiles","preparation":[],"notes":""},{"id":"quest-sins-of-the-father","preparation":[],"notes":"Use the tome of experience on Herblore Herblore six times."},{"id":"quest-beneath-cursed-sands","preparation":[],"notes":""},{"id":"quest-the-curse-of-arrav","preparation":[],"notes":""},{"id":"quest-making-friends-with-my-arm","preparation":[],"notes":""},{"id":"quest-monkey-madness-ii","preparation":[],"notes":"Use both rewards on Magic Magic ."},{"id":"quest-a-night-at-the-theatre","preparation":["Medium Fremennik Diary"],"notes":"Use all four antique lamps on Magic Magic ."},{"id":"quest-dragon-slayer-ii","preparation":[],"notes":"Use all experience rewards on Strength Strength ."},{"id":"quest-secrets-of-the-north","preparation":[],"notes":""},{"id":"quest-while-guthix-sleeps","preparation":[],"notes":""},{"id":"quest-song-of-the-elves","preparation":[],"notes":"To obtain a runite bar , get one as a guaranteed drop from rune dragons , or exchange rune platelegs at the Aldarin windmill nest . Rune platelegs can be purchased at Scavvo's Rune Store in the Champions' Guild for 64,000 ."},{"id":"quest-desert-treasure-ii-the-fallen-empire","preparation":[],"notes":"Use the ancient lamps on any combat skill: it is generally recommended to put them on Prayer Prayer , as this is the hardest skill to train."},{"id":"quest-the-blood-moon-rises","preparation":[],"notes":"Use the six experience tomes on any skill(s) of your choosing above level 70. Herblore Herblore is selected here."}]}},"cape":{"source":"https://oldschool.runescape.wiki/w/Quest_point_cape","revision":15393803,"icon":"data:image/png;base64,","cost":99000}};
